sp_widget.client_script:
api.controller = function () {
    var c = this;

    c.refreshing = false;

    // Re-runs the server script and re-renders the metrics in place
    c.refresh = function () {
        c.refreshing = true;
        c.server.update().then(function () {
            c.refreshing = false;
        });
    };
};

sp_widget.css:
.grievance-sla-dashboard {
    .sla-metric {
        padding: 18px 16px;
        margin-bottom: 12px;
        border: 1px solid $border-color;
        border-left-width: 5px;
        border-radius: $border-radius-base;
        background-color: $panel-bg;
        text-align: center;
    }

    .sla-metric-label {
        margin: 0 0 4px;
        font-size: 13px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.04em;
        color: $text-muted;
    }

    .sla-metric-value {
        margin: 0;
        font-size: 40px;
        line-height: 1.1;
        font-weight: 700;
    }

    .sla-metric-help {
        margin: 6px 0 0;
        font-size: 12px;
        color: $text-muted;
    }

    /* Open grievances - neutral informational accent */
    .sla-metric-open {
        border-left-color: $brand-info;

        .sla-metric-value {
            color: $text-color;
        }
    }

    /* Breach severity mapped from the actual value, not a flat style */
    .sla-metric-ok {
        border-left-color: $brand-success;

        .sla-metric-value {
            color: darken($brand-success, 10%);
        }
    }

    .sla-metric-warning {
        border-left-color: $brand-warning;

        .sla-metric-value {
            color: darken($brand-warning, 12%);
        }
    }

    .sla-metric-critical {
        border-left-color: $brand-danger;

        .sla-metric-value {
            color: darken($brand-danger, 8%);
        }
    }

    .sla-metric-summary {
        padding: 8px 12px;
        border-top: 1px solid $border-color;
        font-size: 13px;
    }

    .sla-metric-empty {
        padding: 12px 0;
    }

    .sla-metric-asof {
        margin: 8px 0 0;
        font-size: 11px;
        text-align: right;
    }
}

sp_widget.script:
(function () {
    // Initialize every data.* property so the template never binds to undefined
    data.openCount = 0;
    data.breachCount = 0;
    data.onTrackCount = 0;
    data.asOf = '';
    data.tableLabel = 'Grievance';

    var TABLE = 'x_1850267_public_0_grievance';

    // Scoped-app-safe "now": new GlideDateTime() is the scoped equivalent of
    // gs.nowDateTime(), which is a global-scope-only API.
    var now = new GlideDateTime();

    // 1) Total open grievances (active = true)
    var openAgg = new GlideAggregate(TABLE);
    openAgg.addQuery('active', true);
    openAgg.addAggregate('COUNT');
    openAgg.query();
    if (openAgg.next()) {
        data.openCount = parseInt(openAgg.getAggregate('COUNT'), 10) || 0;
    }

    // 2) Active SLA breaches (active = true AND target_resolution < now)
    //    Records with an empty target_resolution are excluded - an unset target
    //    cannot be breached.
    var breachAgg = new GlideAggregate(TABLE);
    breachAgg.addQuery('active', true);
    breachAgg.addNotNullQuery('target_resolution');
    breachAgg.addQuery('target_resolution', '<', now);
    breachAgg.addAggregate('COUNT');
    breachAgg.query();
    if (breachAgg.next()) {
        data.breachCount = parseInt(breachAgg.getAggregate('COUNT'), 10) || 0;
    }

    // Derived: open grievances still within their resolution target
    data.onTrackCount = Math.max(0, data.openCount - data.breachCount);

    // Breach rate as a whole percentage of open grievances
    data.breachRate = data.openCount > 0
        ? Math.round((data.breachCount / data.openCount) * 100)
        : 0;

    // Severity class driven by the actual breach count, not hardcoded flat
    if (data.breachCount === 0) {
        data.breachClass = 'sla-metric-ok';
    } else if (data.breachRate >= 25) {
        data.breachClass = 'sla-metric-critical';
    } else {
        data.breachClass = 'sla-metric-warning';
    }

    data.asOf = now.getDisplayValue();
})();
